window.STUDY_BFA_AI=[{"title":"Marché financier : définition, rôle et typologie","label":"PARTIE 1 — PRÉSENTATION DU MARCHÉ FINANCIER","number":1,"notes":[["Définition du marché financier","Le marché financier met en relation des agents qui cherchent des capitaux et des investisseurs qui souhaitent placer leur épargne. Le support le présente principalement comme un marché de financement et de placement à long terme, par opposition au marché monétaire, orienté vers le court terme."],["Quatre rôles essentiels","1) Mettre en relation offreurs et demandeurs de capitaux. 2) Faciliter la revente des titres (liquidité). 3) Former les prix par l’offre et la demande. 4) Orienter les ressources vers les projets à financer."],["Classification économique","Le marché des actions finance les entreprises par leurs capitaux propres ; le marché obligataire finance par l’emprunt ; le marché monétaire concerne les capitaux à court terme ; les produits dérivés servent notamment à couvrir des risques ; le marché des changes permet d’échanger des devises."],["Classification fonctionnelle : primaire et secondaire","Marché primaire : émission et première vente de titres, qui apporte des fonds à l’émetteur. Marché secondaire : revente de titres déjà émis entre investisseurs. La revente sur le secondaire ne constitue pas, en elle-même, un nouveau financement de l’émetteur."],["Classification organisationnelle","Un marché organisé applique des règles communes aux transactions et à l’admission des titres, sous la surveillance d’un régulateur. Un marché de gré à gré (OTC, « over the counter ») permet aux deux parties de négocier directement, hors d’une plateforme boursière centralisée."],["Marché organisé : fonctionnement","Les règles portent notamment sur l’accès au marché, l’admission à la cotation, l’exécution des opérations, la suspension des négociations et la publication des transactions. La Bourse de Casablanca est l’exemple de marché organisé présenté dans le support."],["Avantages du marché organisé","La liquidité facilite les échanges ; la publicité des négociations améliore la transparence ; les règles de règlement et de livraison renforcent la sécurité. Une chambre de compensation peut intervenir selon l’organisation du marché, mais elle n’est pas une caractéristique universelle."],["Liquidité et formation des prix","Un titre est liquide lorsqu’il peut être acheté ou vendu relativement facilement. Son prix résulte de la rencontre entre les intentions d’achat et de vente ; un prix peut varier même si les caractéristiques juridiques du titre restent identiques."]],"cards":[["Un investisseur revend une action déjà cotée à un autre investisseur. Sur quel marché ?","Le secondaire organise l’échange de titres existants."],["Qu’est-ce qu’un marché financier ?","Rencontre entre agents à financer et investisseurs, principalement pour des capitaux à long terme."],["Quels sont les quatre grands rôles du marché financier ?","Financer l’économie, faciliter la liquidité, former les prix et orienter les capitaux vers les projets."],["Quelle différence entre marché financier et marché monétaire ?","Financier : financements à long terme ; monétaire : liquidités à court terme."],["À quoi sert le marché des actions ?","À financer une entreprise par l’émission de titres représentant une part de son capital."],["À quoi sert le marché obligataire ?","À permettre à un émetteur d’emprunter des capitaux auprès d’investisseurs en émettant des titres de dette."],["Qu’est-ce qu’un marché primaire ?","Le marché sur lequel des titres sont émis et vendus pour la première fois aux investisseurs."],["Qu’est-ce qu’un marché secondaire ?","Le marché où des investisseurs achètent et revendent des titres déjà émis."],["Qu’est-ce qu’un marché de gré à gré (OTC) ?","Un marché où les transactions sont négociées directement entre deux parties, sans passer par une bourse centralisée."],["Qu’est-ce qu’un marché organisé ?","Un marché où les transactions suivent des règles communes et sont encadrées par des autorités compétentes."],["Que signifie la liquidité d’un titre ?","La possibilité de l’acheter ou de le vendre facilement, sans devoir attendre longtemps une contrepartie."],["Comment se forme le prix d’un titre sur le marché ?","Par la confrontation entre les ordres ou intentions d’achat et de vente."],["Quel est l’intérêt de la transparence sur un marché organisé ?","Elle permet aux participants de disposer d’informations sur les transactions et de mieux comparer les prix."]],"quiz":[["Un investisseur revend une action déjà cotée à un autre investisseur. Sur quel marché ?",["Secondaire","Primaire","Émission initiale"],0,"Le secondaire organise l’échange de titres existants."],["Quel est le rôle principal du marché financier ?",["Mettre en relation besoins de financement et épargne","Fixer les prix de tous les biens","Remplacer les banques centrales"],0,"Le marché financier met en contact les émetteurs de titres et les investisseurs."],["Une entreprise vend de nouvelles actions pour se financer. Sur quel marché ?",["Le marché secondaire","Le marché primaire","Le marché des changes"],1,"L’émission de titres nouveaux relève du marché primaire."],["Que se passe-t-il sur le marché secondaire ?",["L’État collecte des impôts","Les entreprises créent uniquement des actions","Les investisseurs revendent des titres existants"],2,"Le marché secondaire facilite la circulation des titres après leur émission."],["Quel marché sert principalement aux financements à court terme ?",["Le marché monétaire","Le marché obligataire de long terme","Le marché des actions"],0,"Le marché monétaire traite surtout des besoins de liquidité à court terme."],["Que signifie OTC ?",["Un marché obligatoirement public","Une transaction négociée de gré à gré","Une action réservée aux banques"],1,"OTC désigne les transactions négociées directement entre contreparties."],["Pourquoi un marché secondaire actif est-il utile ?",["Il garantit un bénéfice à chaque investisseur","Il supprime le risque de crédit","Il facilite l’achat et la revente des titres"],2,"La liquidité permet aux investisseurs de céder leurs titres plus facilement."],["Quel mécanisme contribue à déterminer le prix d’un titre ?",["La rencontre entre offre et demande","Le seul prix historique d’émission","La décision de l’investisseur vendeur uniquement"],0,"Les transactions confrontent les prix proposés par acheteurs et vendeurs."],["Quel avantage caractérise un marché organisé ?",["L’absence totale de risques","Des règles de négociation et davantage de transparence","Des prix toujours fixes"],1,"Les règles et la publication des échanges favorisent la transparence et la sécurité."]],"map":[["Marché financier","Financement et placement à long terme"],["Rôles","Financement · Liquidité · Prix · Allocation"],["Marché primaire","Première émission de titres"],["Marché secondaire","Revente de titres existants"],["Organisé","Règles · Surveillance · Transparence"],["Gré à gré (OTC)","Négociation directe"],["Marchés économiques","Actions · Obligations · Monétaire · Dérivés · Changes"]],"conceptLinks":[["Offreurs ↔ demandeurs","Le marché met l’épargne des investisseurs au service des agents à financer."],["Primaire → secondaire","Le premier finance l’émetteur par des titres nouveaux ; le second permet leur revente."],["Organisation","Distinguer marché organisé et gré à gré, puis classer selon les instruments."]]},{"title":"Marché primaire : intervenants et actions","label":"PARTIE 1 — PRÉSENTATION DU MARCHÉ FINANCIER","number":2,"notes":[["Qui demande des capitaux sur le marché primaire ?","Les entreprises émettent des actions ou des obligations pour financer leurs projets. L’État et les collectivités territoriales peuvent recourir à des emprunts obligataires pour couvrir leurs besoins de financement."],["Qui offre des capitaux ?","Les ménages, les investisseurs institutionnels (assurances, caisses de retraite, CDG, OPCVM), les banques et les investisseurs étrangers placent des ressources sur le marché primaire."],["Appel public à l’épargne","L’émetteur sollicite l’épargne des investisseurs par l’émission de titres. Une action représente des capitaux propres ; une obligation représente une dette à rembourser selon les conditions prévues."],["Valeurs mobilières : deux familles","Les valeurs mobilières sont des titres négociables qui donnent à leur détenteur des droits. Une action donne la qualité d’associé ; une obligation donne la qualité de créancier."],["Définition et droits de l’actionnaire","L’action représente une fraction du capital d’une société par actions. Son détenteur peut bénéficier des distributions de bénéfices et dispose de droits sociaux, notamment un droit de vote selon la catégorie d’action."],["Actions de numéraire et actions d’apport","Une action de numéraire est émise en contrepartie d’un apport d’argent. Une action d’apport rémunère un apport en nature, comme un bien transféré à la société."],["Actions au porteur et nominatives","Pour une action au porteur, la propriété est constatée par inscription auprès d’un intermédiaire et l’émetteur n’identifie pas nécessairement directement le titulaire. Pour une action nominative, le nom du détenteur figure dans les registres tenus pour l’émetteur."],["Valeur nominale de l’action (VN)","La valeur nominale représente la fraction du capital social attachée à une action. Ce n’est pas son cours boursier : elle sert de référence juridique et comptable."],["Prix d’émission (VE) et prime d’émission","Le prix d’émission est le prix payé lors de la souscription d’une action nouvelle.\nLorsque ce prix dépasse la valeur nominale, la différence correspond à une prime d’émission : prime = prix d’émission − valeur nominale."],["Valeur de marché","La valeur de marché est le cours auquel l’action cotée se négocie. Elle varie avec l’offre, la demande et la liquidité ; elle peut être différente de la valeur nominale et du prix d’émission."]],"cards":[["Valeur nominale 100 DH, prix d’émission 135 DH : quelle prime par action ?","Prime = prix d’émission − valeur nominale = 35 DH."],["Quels agents demandent des capitaux sur le marché primaire ?","Notamment les entreprises, l’État et les collectivités territoriales, selon les titres qu’ils peuvent émettre."],["Quels agents offrent des capitaux sur le marché primaire ?","Les ménages, banques, investisseurs institutionnels et investisseurs étrangers qui souscrivent les titres."],["Qu’est-ce qu’un investisseur institutionnel ?","Organisme plaçant des fonds pour des tiers : assureur, caisse de retraite, OPCVM, etc."],["Qu’est-ce qu’une valeur mobilière ?","Un titre négociable qui représente un droit, notamment une participation au capital ou une créance."],["Quelle différence fondamentale entre action et obligation ?","L’action représente une part du capital ; l’obligation représente une dette de l’émetteur envers l’investisseur."],["Quel droit principal l’action confère-t-elle ?","La qualité d’associé, avec des droits financiers et, selon le titre, des droits de vote."],["Quelle différence entre action de numéraire et action d’apport ?","L’action de numéraire rémunère un apport en argent ; l’action d’apport rémunère un apport en nature."],["Quelle différence entre action au porteur et nominative ?","Nominative : titulaire inscrit chez l’émetteur ; au porteur : inscription chez un intermédiaire."],["Que représente la valeur nominale d’une action ?","La part du capital social correspondant juridiquement à une action, et non son prix de marché."],["Qu’est-ce que le prix d’émission d’une action ?","Le montant demandé aux investisseurs pour souscrire une action nouvellement émise."],["Comment calculer la prime d’émission ?","Prime d’émission = prix d’émission − valeur nominale, lorsque le prix d’émission est supérieur au nominal."],["Qu’est-ce que la valeur de marché d’une action ?","Le cours auquel l’action est échangée sur le marché, déterminé par l’offre et la demande."]],"quiz":[["Valeur nominale 100 DH, prix d’émission 135 DH : quelle prime par action ?",["35 DH","235 DH","100 DH"],0,"Prime = prix d’émission − valeur nominale = 35 DH."],["Une entreprise émet des actions nouvelles. Elle cherche à :",["Revendre ses propres créances","Lever des capitaux propres","Rembourser automatiquement toutes ses dettes"],1,"L’émission d’actions permet d’obtenir un financement en capital."],["Quel agent peut être un offreur de capitaux ?",["Une caisse de retraite qui investit","Une entreprise qui demande un prêt","Une collectivité qui émet un emprunt"],0,"Une caisse de retraite investit l’épargne qu’elle gère."],["Que reçoit le souscripteur d’une action ?",["Une garantie de remboursement du nominal","Un coupon obligataire contractuel","Une participation au capital de la société"],2,"L’action est un titre de propriété et non une créance."],["Une action de numéraire est émise contre :",["Un apport en nature","Un versement d’argent","Une obligation existante uniquement"],1,"Une action de numéraire correspond à un apport monétaire."],["Que représente la valeur nominale d’une action ?",["Une fraction du capital social","Le cours de bourse du jour","Le dividende annuel"],0,"La valeur nominale est une valeur attachée au capital de la société."],["La prime d’émission correspond à :",["La valeur nominale plus le dividende","La valeur de marché moins l’impôt","La différence entre prix d’émission et valeur nominale"],2,"La prime apparaît quand la souscription se fait au-dessus du nominal."],["Quelle action identifie le titulaire dans les registres de l’émetteur ?",["L’action de numéraire","L’action nominative","L’action obligataire"],1,"La forme nominative permet l’identification du propriétaire."],["Pourquoi le cours d’une action cotée change-t-il ?",["Parce que l’offre et la demande évoluent","Parce que la valeur nominale change chaque jour","Parce que l’État fixe chaque transaction"],0,"La valeur de marché évolue selon les transactions et les anticipations des investisseurs."]],"map":[["Demandeurs","Entreprises · État · Collectivités"],["Offreurs","Ménages · Institutionnels · Banques · Étrangers"],["Titres","Actions = capital · Obligations = dette"],["Action","Droits d’associé"],["Formes","Numéraire · Apport · Porteur · Nominative"],["Valeur nominale","Part du capital social"],["Prix d’émission","Souscription de l’action nouvelle"],["Prime d’émission","Prix d’émission − valeur nominale"],["Valeur de marché","Cours de bourse variable"]],"conceptLinks":[["Émission","L’entreprise émet des actions pour obtenir des capitaux propres."],["Actionnaire","Le détenteur possède une fraction du capital, contrairement à un créancier."],["Valeurs","Le prix d’émission peut dépasser la valeur nominale : la différence est la prime d’émission."]]},{"title":"Obligations et fonctionnement du marché secondaire","label":"PARTIE 1 — PRÉSENTATION DU MARCHÉ FINANCIER","number":3,"notes":[["L’obligation : un titre de créance","Une obligation représente une fraction d’un emprunt. L’émetteur doit respecter les conditions de paiement des intérêts et de remboursement prévues ; le détenteur est un créancier, pas un associé."],["Actionnaire et obligataire : droits différents","L’actionnaire participe au capital et peut percevoir des dividendes, sans remboursement automatique de son apport. L’obligataire possède une créance, reçoit les paiements contractuels et ne dispose pas de droit de vote lié à la gestion par cette seule obligation."],["Risque et priorité de remboursement","Le porteur d’une obligation est normalement remboursé avant les actionnaires en cas de liquidation, mais il supporte tout de même un risque de défaut de l’émetteur. La priorité exacte dépend de la catégorie de dette, notamment si elle est subordonnée."],["Caractéristiques principales d’une obligation","Valeur nominale : référence de calcul des intérêts. Prix d’émission : montant payé lors de la souscription. Coupon : intérêt versé. Prix de remboursement : montant payé à l’échéance. Modalité d’amortissement : calendrier de restitution du capital."],["Coupon annuel","Pour une obligation à taux fixe, le coupon annuel se calcule généralement ainsi : coupon = valeur nominale × taux facial. Le prix d’achat du titre peut être différent de sa valeur nominale."],["Durée résiduelle et formes de détention","La durée résiduelle est le temps restant jusqu’au remboursement. Le support distingue des obligations de court, moyen et long terme. Il présente aussi les titres au porteur et les titres nominatifs."],["Obligations indexées et convertibles","Une obligation indexée fait varier le coupon ou le remboursement selon un indice ou une référence prévue. Une obligation convertible en actions permet, sous certaines conditions, d’échanger le titre de dette contre des actions."],["Marché secondaire : définition","Sur le marché secondaire, les investisseurs échangent des titres déjà émis. Le prix dépend des offres d’achat et de vente ; l’émetteur ne reçoit pas directement le produit de chaque revente."],["Trois fonctions du marché secondaire","Il apporte de la liquidité aux placements, permet la formation de prix observables et contribue indirectement au financement primaire : un titre facilement revendable attire plus facilement des souscripteurs lors de nouvelles émissions."],["Lien entre les deux marchés","Le marché primaire crée le titre et apporte des capitaux à l’émetteur. Le marché secondaire organise sa circulation entre investisseurs. Les prix du secondaire peuvent influencer les conditions de nouvelles émissions."]],"cards":[["Nominal 1 000 DH et taux facial annuel fixe 6 %. Quel coupon annuel ?","1 000 × 0,06 = 60 DH."],["Que représente une obligation pour son détenteur ?","Une créance sur l’émetteur, qui prévoit des paiements d’intérêts et un remboursement selon les conditions de l’emprunt."],["Quelle différence entre actionnaire et obligataire ?","L’actionnaire détient une part du capital ; l’obligataire est créancier de l’émetteur."],["L’obligataire dispose-t-il d’un droit de vote du seul fait de son obligation ?","Non. Une obligation donne un droit de créance, pas la qualité d’associé avec droit de vote."],["Une obligation est-elle sans risque ?","Non. L’émetteur peut faire défaut et le cours du titre peut varier, même si les paiements sont contractuellement prévus."],["Que signifie la durée résiduelle d’une obligation ?","Le temps qui reste avant l’échéance de remboursement du titre."],["Qu’est-ce qu’une obligation indexée ?","Une obligation dont le coupon ou le remboursement dépend d’une valeur de référence prévue au contrat."],["Comment le marché secondaire favorise-t-il indirectement le marché primaire ?","La possibilité de revendre un titre rend les nouvelles émissions plus attractives pour les investisseurs."]],"quiz":[["Nominal 1 000 DH et taux facial annuel fixe 6 %. Quel coupon annuel ?",["60 DH","600 DH","6 DH"],0,"1 000 × 0,06 = 60 DH."],["L’acheteur d’une obligation devient :",["Un associé disposant toujours d’un vote","Un créancier de l’émetteur","Le dirigeant de l’entreprise"],1,"L’obligation matérialise une dette pour l’émetteur et une créance pour l’investisseur."],["Pour une obligation à taux fixe, le coupon est calculé sur :",["La valeur nominale et le taux facial","Le cours boursier du jour uniquement","Le dividende de l’entreprise"],0,"Le coupon contractuel est généralement le nominal multiplié par le taux facial."],["Le détenteur d’une obligation supporte notamment :",["Un risque lié seulement aux fluctuations de son dividende","Un risque de variation du prix mais aucun risque de non-remboursement","Un risque de défaut de l’émetteur"],2,"Le contrat n’élimine pas le risque que l’émetteur ne puisse pas payer."],["Une obligation convertible donne :",["Un remboursement immédiat garanti","Une possibilité de conversion en actions","Un droit automatique de diriger l’entreprise"],1,"La conversion en actions dépend des modalités prévues pour le titre."],["À quoi correspond la durée résiduelle ?",["Au temps restant jusqu’au remboursement","Au nombre d’années depuis la création de la société","À la durée de la séance boursière"],0,"La durée résiduelle mesure le temps séparant le titre de son échéance."],["Sur le marché secondaire, qui échange les titres ?",["L’émetteur avec les souscripteurs lors d’une nouvelle émission","La banque centrale lorsqu’elle fixe les conditions d’émission","Les investisseurs qui achètent et revendent des titres existants"],2,"La transaction secondaire se fait entre détenteurs et acquéreurs de titres déjà émis."],["Pourquoi un marché secondaire liquide aide-t-il les nouvelles émissions ?",["Il fixe un rendement certain","Il rassure les investisseurs sur la possibilité de revendre","Il supprime le risque de faillite"],1,"Une possibilité de sortie rend le placement plus intéressant."],["Quelle différence résume les marchés primaire et secondaire ?",["Émission initiale puis revente entre investisseurs","Marché des devises puis marché monétaire","Prêt bancaire puis paiement de salaires"],0,"Le primaire sert au financement initial, le secondaire à la négociation ultérieure."]],"map":[["Obligation","Titre de créance"],["Émetteur","Dette et remboursement"],["Obligataire","Coupons · Créance · Risque de défaut"],["Coupon","Nominal × taux facial"],["Valeurs","Nominal · Émission · Remboursement"],["Formes","Porteur · Nominatif · Indexé · Convertible"],["Marché secondaire","Échange de titres existants"],["Fonctions","Liquidité · Prix · Transparence"],["Lien primaire","Revente possible = émission plus attractive"]],"conceptLinks":[["Obligation : dette et créance","L’émetteur doit les flux prévus ; le porteur détient une créance."],["Coupon","Pour un taux fixe annuel, le nominal multiplié par le taux facial donne le coupon annuel."],["Circulation","Le marché secondaire permet de revendre le titre avant l’échéance."]]},{"title":"OPCVM et intervenants du marché marocain","label":"PARTIE 1 — PRÉSENTATION DU MARCHÉ FINANCIER","number":4,"notes":[["Définition d’un OPCVM","Un Organisme de Placement Collectif en Valeurs Mobilières (OPCVM) collecte l’épargne de plusieurs investisseurs et la place dans un portefeuille de titres. Les placements suivent une politique de gestion annoncée à l’avance."],["Intérêt de la gestion collective","En regroupant les fonds, un OPCVM donne accès à une gestion spécialisée et à une diversification des placements. La diversification répartit les risques mais ne garantit pas l’absence de pertes."],["SICAV : Société d’Investissement à Capital Variable","La SICAV prend la forme d’une société. L’investisseur détient des actions de cette société et possède des droits attachés à cette qualité, notamment selon les règles de la SICAV."],["FCP : Fonds Commun de Placement","Le FCP est une copropriété de valeurs mobilières sans personnalité morale. L’investisseur détient des parts ; une société de gestion administre le fonds pour le compte des porteurs."],["SICAV et FCP : différence essentielle","SICAV : l’investisseur est actionnaire d’une société d’investissement. FCP : il est porteur de parts d’un fonds géré par un établissement spécialisé."],["Bourse de Casablanca","Elle organise les échanges des titres admis à la négociation et met à disposition l’infrastructure du marché organisé. Elle intervient dans la transparence et le bon déroulement des transactions."],["AMMC : autorité de régulation","L’Autorité Marocaine du Marché des Capitaux (AMMC) surveille le marché, protège les investisseurs et veille à la transparence et au respect des règles applicables."],["Sociétés de bourse et négociateurs","Les sociétés de bourse reçoivent et exécutent des ordres d’achat et de vente pour les investisseurs. Les négociateurs interviennent dans l’exécution des transactions sur le marché."],["Investisseurs et émetteurs","Les investisseurs particuliers placent leur épargne ; les investisseurs institutionnels gèrent des capitaux importants. Les sociétés cotées émettent des titres et communiquent des informations financières aux investisseurs."],["Sociétés de gestion et banques dépositaires","Les sociétés de gestion choisissent et suivent les placements de fonds comme les SICAV et FCP. Les banques dépositaires assurent notamment la garde des titres et interviennent dans les opérations de règlement."],["Compensation et tenue de marché","Les acteurs de compensation participent au bon dénouement des transactions (paiement et livraison). Les teneurs de marché affichent des prix d’achat et de vente pour faciliter les échanges et soutenir la liquidité."]],"cards":[["Un investisseur veut passer un ordre d’achat en bourse. Quel intervenant exécute cet ordre ?","La société de bourse exécute les ordres ; l’AMMC régule."],["Qu’est-ce qu’un OPCVM ?","Un organisme qui regroupe l’épargne de plusieurs investisseurs pour l’investir dans un portefeuille de valeurs mobilières."],["Pourquoi un OPCVM diversifie-t-il ses placements ?","Pour répartir les risques entre plusieurs titres plutôt que concentrer tout le capital sur un seul actif."],["Qu’est-ce qu’une SICAV ?","Une Société d’Investissement à Capital Variable : l’investisseur y détient des actions d’une société d’investissement."],["Qu’est-ce qu’un FCP ?","Un Fonds Commun de Placement : une copropriété de titres sans personnalité morale, gérée pour les porteurs de parts."],["Quelle différence entre SICAV et FCP ?","Dans une SICAV, l’investisseur est actionnaire ; dans un FCP, il est porteur de parts."],["Quel est le rôle de la Bourse de Casablanca ?","Organiser et faciliter les négociations des titres admis sur le marché boursier marocain."],["Que signifie AMMC ?","Autorité Marocaine du Marché des Capitaux, chargée notamment de la régulation et de la protection des investisseurs."],["Que fait une société de bourse ?","Elle exécute les ordres d’achat et de vente de titres pour le compte des investisseurs."],["Quel est le rôle d’une société de gestion d’actifs ?","Gérer un portefeuille de placements selon une stratégie et les intérêts des investisseurs."],["Quel est le rôle d’une banque dépositaire ?","Assurer notamment la conservation des titres et intervenir dans le règlement des opérations."],["À quoi sert un teneur de marché ?","À proposer des prix d’achat et de vente pour faciliter les transactions et améliorer la liquidité."]],"quiz":[["Un investisseur veut passer un ordre d’achat en bourse. Quel intervenant exécute cet ordre ?",["Société de bourse","AMMC","Dépositaire uniquement"],0,"La société de bourse exécute les ordres ; l’AMMC régule."],["Un OPCVM sert principalement à :",["Collecter l’épargne pour investir collectivement","Fixer les impôts des investisseurs","Garantir le rendement des actions"],0,"L’OPCVM regroupe des capitaux et les investit selon une politique définie."],["Dans un FCP, l’investisseur détient :",["Une obligation de l’État","Des parts d’un fonds","Un compte courant bancaire uniquement"],1,"Le FCP est une copropriété de valeurs mobilières, sans personnalité morale."],["Quelle structure donne à l’investisseur la qualité d’actionnaire ?",["Le FCP","Le marché OTC","La SICAV"],2,"La SICAV est constituée sous forme de société d’investissement."],["Quelle autorité protège et surveille le marché des capitaux marocain ?",["L’AMMC","La seule société de bourse","Le teneur de marché"],0,"L’AMMC est l’autorité marocaine de régulation du marché des capitaux."],["Une société de bourse intervient surtout pour :",["Fixer le taux d’imposition","Exécuter les ordres de titres","Créer les bilans des entreprises"],1,"Les sociétés de bourse sont des intermédiaires de négociation."],["Quel acteur conserve notamment les titres pour les fonds ?",["Le teneur de marché","L’émetteur de tous les titres","La banque dépositaire"],2,"La banque dépositaire assure notamment la garde des actifs."],["Pourquoi un teneur de marché affiche-t-il des prix d’achat et de vente ?",["Pour soutenir la liquidité des échanges","Pour garantir le bénéfice de chaque investisseur","Pour supprimer la réglementation"],0,"L’affichage de prix permet plus facilement de trouver une contrepartie."],["La diversification d’un OPCVM signifie que :",["Le capital est sans risque","Les placements sont répartis entre plusieurs actifs","Les rendements sont toujours identiques"],1,"La diversification réduit la concentration du risque sans éliminer toute perte possible."]],"map":[["OPCVM","Gestion collective de l’épargne"],["SICAV","Société · Investisseur actionnaire"],["FCP","Copropriété · Porteur de parts"],["Bourse de Casablanca","Organisation des négociations"],["AMMC","Régulation · Protection"],["Sociétés de bourse","Exécution des ordres"],["Sociétés de gestion","Gestion des fonds"],["Banques dépositaires","Conservation et règlement"],["Teneurs de marché","Prix acheteur/vendeur · Liquidité"]],"conceptLinks":[["OPCVM","L’épargne est regroupée et investie collectivement ; SICAV et FCP diffèrent juridiquement."],["Régulation","L’AMMC veille au respect des règles et à la protection des investisseurs."],["Intermédiation","Sociétés de bourse, gestionnaires et dépositaires remplissent des fonctions distinctes."]]},{"title":"Marché obligataire : émission et remboursement","label":"PARTIE 2 — MARCHÉ OBLIGATAIRE","number":5,"notes":[["Définition d’une obligation","Une obligation est un titre négociable représentant une dette pour l’émetteur et une créance pour l’investisseur. Le détenteur a droit aux paiements prévus par le contrat, sans devenir associé de l’émetteur."],["Qui peut émettre des obligations ?","Le support cite notamment l’État, les entreprises publiques et les sociétés de capitaux privées. Le financement obtenu constitue une dette à rembourser, contrairement à une émission d’actions."],["Valeur nominale (VN)","La valeur nominale est le montant de référence de l’obligation. Pour un titre à taux fixe, elle sert généralement de base au calcul du coupon."],["Taux nominal ou taux facial (TN)","Le taux facial est le taux d’intérêt contractuel utilisé pour calculer le coupon.\nPour un coupon annuel à taux fixe : coupon annuel = VN × TN."],["Prix d’émission (VE)","Le prix d’émission est le montant payé par le souscripteur sur le marché primaire.\nUne obligation peut être émise au pair (VE = VN), sous le pair (VE < VN) ou au-dessus du pair (VE > VN)."],["Prix de remboursement (VR)","Le prix de remboursement est le montant prévu pour restituer le capital à l’échéance ou selon le calendrier d’amortissement. Il peut être égal ou différent de la valeur nominale, selon les clauses du titre."],["Taux de rendement actuariel (TRA)","Le TRA est le taux qui égalise le prix payé et la valeur actuelle des flux futurs de l’obligation : coupons et remboursement. Il dépend donc du prix d’achat, des coupons, de l’échéance et du remboursement, pas seulement du taux facial."],["Lien entre prix d’émission et rendement","Dans le tableau du support, à coupons et remboursement au pair comparables : émission au pair → TRA = TN ; émission sous le pair → TRA > TN ; émission au-dessus du pair → TRA < TN. Ces relations supposent que les autres conditions restent identiques."],["Remboursement in fine","L’émetteur verse les intérêts aux dates prévues et rembourse la totalité du capital en une seule fois à l’échéance.\nPour un taux fixe : intérêt périodique = capital de référence × taux de la période."],["Amortissements constants","Une même part de capital est remboursée à chaque période : amortissement du capital = K / n. Les intérêts portent sur le capital restant dû, qui diminue ; les paiements totaux diminuent donc généralement avec le temps."],["Annuités constantes","Chaque paiement total (intérêt + remboursement de capital) est identique.\nPour un capital K, un taux périodique i et n périodes : annuité a = K × i / [1 − (1 + i)^(-n)]. La part d’intérêt diminue et la part de capital augmente au fil du temps."],["Ne pas confondre coupon et annuité","Le coupon rémunère le prêteur par des intérêts. Une annuité de remboursement peut comprendre à la fois des intérêts et une fraction du capital. Dans un remboursement in fine, le capital n’est restitué qu’à la fin."]],"cards":[["Emprunt de 120 000 DH remboursé par amortissements constants sur 4 périodes. Quel capital amorti par période ?","Amortissement constant = K/n = 30 000 DH."],["Que signifie VN pour une obligation ?","Valeur nominale : montant de référence du titre, notamment pour le calcul du coupon à taux fixe."],["Que signifie TN ou taux facial ?","Le taux d’intérêt contractuel appliqué au nominal pour calculer le coupon."],["Quelle est la formule du coupon annuel à taux fixe ?","Coupon annuel = valeur nominale × taux facial annuel."],["Que signifie VE pour une obligation ?","Prix d’émission : montant payé par le souscripteur lors de l’émission du titre."],["Que signifie VR pour une obligation ?","Prix ou valeur de remboursement : montant de capital prévu à restituer selon les conditions du titre."],["Que signifie une émission au pair ?","Le prix d’émission est égal à la valeur nominale : VE = VN."],["Que signifie une émission sous le pair ?","Le prix d’émission est inférieur à la valeur nominale : VE < VN."],["Qu’est-ce que le taux de rendement actuariel (TRA) ?","Le taux qui rend la valeur actuelle des coupons et du remboursement égale au prix payé pour l’obligation."],["Que signifie un remboursement in fine ?","Le capital est remboursé en une seule fois à l’échéance ; les intérêts sont versés selon le contrat."],["Comment calculer un amortissement constant du capital ?","Amortissement périodique = capital initial K / nombre de périodes n."],["Comment calculer les intérêts sur le capital restant dû ?","Intérêts de la période = capital restant dû × taux d’intérêt de la période."],["Quelle est la formule d’une annuité constante ?","a = K × i / [1 − (1 + i)^(-n)], où K est le capital, i le taux périodique et n le nombre de périodes."],["Quelle différence entre amortissements constants et annuités constantes ?","Amortissements constants : même capital remboursé chaque période ; annuités constantes : même paiement total intérêts + capital."]],"quiz":[["Emprunt de 120 000 DH remboursé par amortissements constants sur 4 périodes. Quel capital amorti par période ?",["30 000 DH","40 000 DH","120 000 DH"],0,"Amortissement constant = K/n = 30 000 DH."],["Le coupon annuel d’une obligation à taux fixe dépend principalement :",["Du cours de bourse de l’action","De la valeur nominale et du taux facial","Du bénéfice net de l’émetteur"],1,"Le coupon contractuel se calcule généralement par VN × taux facial."],["Une obligation émise au pair a :",["VE = VN","VE < VN","VE > VN"],0,"Au pair signifie que le prix d’émission égale la valeur nominale."],["Une émission sous le pair signifie :",["Le coupon est nul","Le capital n’est jamais remboursé","Le prix d’émission est inférieur au nominal"],2,"Le souscripteur paie moins que la valeur nominale du titre."],["À quoi sert le taux de rendement actuariel ?",["À déterminer le nombre d’actionnaires","À relier le prix de l’obligation à la valeur actuelle de ses flux futurs","À remplacer la valeur nominale"],1,"Le TRA est le taux d’actualisation cohérent avec les coupons, le remboursement et le prix."],["Avec un remboursement in fine, le capital est remboursé :",["En une seule fois à l’échéance","En parts égales à chaque période","À chaque paiement de coupon en totalité"],0,"In fine désigne le remboursement du principal à la fin."],["Dans un remboursement par amortissements constants :",["La fraction de capital varie afin de conserver une même annuité","Le capital est remboursé intégralement à la dernière échéance","La part de capital remboursée est identique à chaque période"],2,"Le capital est amorti par fractions égales ; les intérêts suivent le capital restant dû."],["Dans une annuité constante, que reste-t-il identique ?",["La part d’intérêt","Le paiement total intérêts plus capital","La fraction de capital remboursée"],1,"L’annuité totale est constante, même si sa composition évolue."],["Quelle formule exprime l’intérêt de la période sur un emprunt amortissable ?",["Capital restant dû × taux de la période","Capital initial / nombre de périodes","Prix d’émission − valeur nominale"],0,"Les intérêts se calculent sur le capital encore dû."],["Quand le capital restant dû diminue, les intérêts à taux fixe :",["Ils sont calculés sur le capital initial sans tenir compte des remboursements","Ils augmentent car une plus grande part de capital a déjà été remboursée","Diminuent généralement"],2,"À taux inchangé, les intérêts diminuent avec la base de calcul."],["Le prix d’émission d’une obligation est :",["Le dernier cours de l’action","Le montant payé lors de la souscription initiale","Le montant du coupon déjà couru"],1,"Le prix d’émission concerne l’achat initial du titre sur le marché primaire."]],"map":[["Obligation","Dette de l’émetteur · Créance du porteur"],["Valeur nominale","Base du coupon"],["Taux facial","Coupon = VN × TN"],["Prix d’émission","Au pair · Sous le pair · Au-dessus"],["Prix de remboursement","Capital restitué"],["TRA","Actualisation des flux futurs"],["In fine","Capital payé à l’échéance"],["Amortissements constants","Capital remboursé = K/n"],["Annuités constantes","Paiement a = K i/[1−(1+i)^−n]"]],"conceptLinks":[["Conditions d’émission","Nominal, taux facial, prix d’émission et remboursement déterminent les flux et le rendement."],["Amortissement","In fine rembourse le capital à l’échéance ; amortissement constant rembourse la même fraction à chaque période."],["Annuité constante","Paiement total stable ; la part d’intérêt diminue tandis que la part de capital augmente."]]},{"title":"Cotation et évaluation des obligations","label":"PARTIE 2 — MARCHÉ OBLIGATAIRE","number":6,"notes":[["Comment est cotée une obligation ?","Le cours d’une obligation est généralement exprimé en pourcentage de sa valeur nominale. Une cotation de 100 signifie 100 % du nominal ; une cotation supérieure à 100 signifie que le cours dépasse le nominal."],["Cotation au pied du coupon","Le cours affiché est dit « au pied du coupon » : il n’inclut pas les intérêts courus depuis le dernier paiement. On parle aussi de prix hors coupon couru (clean price)."],["Coupon couru","Le coupon couru correspond aux intérêts accumulés depuis le dernier versement et jusqu’à la date de transaction. L’acheteur le verse en plus du cours au vendeur, qui a détenu l’obligation pendant cette période."],["Calcul du coupon couru : base 365","Selon la convention du support, coupon couru en % du nominal = taux facial annuel × (nombre de jours écoulés / 365).\nEn montant : coupon couru = VN × taux facial × (jours / 365)."],["Prix payé lors de l’achat","Pour une obligation cotée au pied du coupon : prix total payé = prix coté (converti en montant) + coupon couru en montant. Il faut donc distinguer le cours affiché du montant réellement réglé."],["Prix d’une obligation à taux fixe","Le prix théorique est la somme des coupons futurs actualisés et de la valeur de remboursement actualisée : P = Σ [C_t / (1 + r)^t] + VR / (1 + r)^n, avec r le rendement par période."],["Formule avec coupons constants","Lorsque le coupon C est constant à chaque période : P = C × [1 − (1 + r)^(-n)] / r + VR × (1 + r)^(-n), pour r non nul. Les périodes du taux et des coupons doivent être cohérentes."],["Prix d’une obligation zéro coupon","Une obligation zéro coupon ne verse pas d’intérêts périodiques : elle paie un montant à l’échéance.\nSa valeur actuelle est P = VR / (1 + r)^n."],["Relation entre taux de marché et prix","À flux futurs fixes, une hausse du taux de rendement exigé fait baisser le prix de l’obligation. Une baisse du taux exigé fait augmenter le prix. Cette relation est inverse."],["Prix, coupon et rendement : trois notions","Le coupon est le revenu contractuel du titre ; le prix est le montant auquel il s’échange ; le rendement actuariel tient compte du prix payé et de tous les flux futurs. Ils ne doivent pas être confondus."]],"cards":[["Prix coté converti en montant = 980 DH ; coupon couru = 12 DH. Quel montant total payé hors frais ?","Prix total = prix coté + coupon couru = 992 DH."],["Comment exprime-t-on généralement la cotation d’une obligation ?","En pourcentage de sa valeur nominale, et non directement comme un montant monétaire."],["Que signifie une cotation obligataire de 100 ?","Le cours coté correspond à 100 % de la valeur nominale, avant ajout éventuel du coupon couru."],["Que signifie « cotation au pied du coupon » ?","Le cours affiché exclut les intérêts courus depuis le dernier paiement de coupon."],["Qu’est-ce que le coupon couru ?","La part des intérêts accumulés depuis le dernier coupon jusqu’à la date de transaction."],["Comment calculer le coupon couru en % du nominal, sur base 365 ?","Coupon couru (%) = taux facial annuel (%) × nombre de jours écoulés / 365."],["Comment calculer le coupon couru en montant ?","Coupon couru = valeur nominale × taux facial annuel × nombre de jours écoulés / 365."],["Comment obtenir le prix total d’achat d’une obligation cotée au pied du coupon ?","Prix total payé = prix coté exprimé en montant + coupon couru en montant."],["Comment calcule-t-on le prix théorique d’une obligation ?","En additionnant la valeur actuelle de tous les coupons futurs et la valeur actuelle du remboursement."],["Quelle formule valorise une obligation à coupon constant ?","P = C × [1 − (1 + r)^(-n)] / r + VR / (1 + r)^n, avec C coupon périodique et r rendement par période."],["Quelle formule valorise une obligation zéro coupon ?","P = VR / (1 + r)^n, où VR est le remboursement, r le rendement périodique et n le nombre de périodes."],["Quelle différence entre taux facial et rendement actuariel ?","Le taux facial sert au calcul du coupon ; le rendement actuariel dépend du prix payé et de l’ensemble des flux futurs."]],"quiz":[["Prix coté converti en montant = 980 DH ; coupon couru = 12 DH. Quel montant total payé hors frais ?",["992 DH","968 DH","980 DH"],0,"Prix total = prix coté + coupon couru = 992 DH."],["Une obligation cotée à 100 se négocie au pied du coupon à :",["100 % de sa valeur nominale","100 dirhams quel que soit le nominal","100 % de son coupon annuel"],0,"La cotation obligataire est exprimée en pourcentage du nominal."],["La cotation au pied du coupon exclut :",["La valeur nominale","Le coupon couru","La valeur de remboursement future"],1,"Le cours hors coupon couru ne comprend pas les intérêts accumulés."],["Pour connaître le prix total à régler, il faut :",["Retirer le coupon couru","Multiplier le prix coté par le nombre d’actionnaires","Ajouter le coupon couru au prix coté exprimé en montant"],2,"Le prix payé inclut le cours et les intérêts courus dus au vendeur."],["Selon le support, le coupon couru sur base 365 dépend :",["Du taux facial et du nombre de jours écoulés","Du dividende de l’action","Uniquement de la date d’émission de l’entreprise"],0,"Le coupon couru est proportionnel à la durée depuis le dernier versement."],["Le prix théorique d’une obligation correspond :",["À la valeur nominale dans tous les cas","À la somme actualisée des flux futurs","Au seul montant des coupons passés"],1,"On actualise les coupons futurs et le remboursement."],["Une obligation zéro coupon verse :",["Un coupon à chaque mois","Un dividende annuel","Un montant à l’échéance sans coupon périodique"],2,"Les intérêts sont intégrés dans la différence entre prix d’achat et remboursement."],["Si le rendement exigé par le marché augmente, le prix d’une obligation à taux fixe :",["Baisse","Le prix monte car les coupons contractuels deviennent plus élevés","Le prix reste proche du nominal indépendamment de l’actualisation"],0,"Un taux d’actualisation plus élevé réduit la valeur actuelle des flux fixes."],["Le taux facial se distingue du rendement actuariel car :",["Ils sont nécessairement identiques","Le premier fixe le coupon, le second tient compte du prix et des flux futurs","Le premier est le taux d’inflation"],1,"Le rendement actuariel dépend des conditions d’achat et de remboursement."],["Pour une obligation zéro coupon, quelle formule donne la valeur actuelle ?",["P = VR × (1+r)^n","P = VN × taux facial","P = VR / (1+r)^n"],2,"On actualise le paiement unique prévu à l’échéance."]],"map":[["Cotation","% de la valeur nominale"],["Pied du coupon","Cours sans intérêts courus"],["Coupon couru","VN × taux × jours/365"],["Prix total","Cours en montant + coupon couru"],["Valeur actuelle","Coupons actualisés + remboursement actualisé"],["Zéro coupon","VR/(1+r)^n"],["Taux ↑","Prix de l’obligation ↓"],["Taux ↓","Prix de l’obligation ↑"],["Taux facial","Coupon contractuel ≠ rendement actuariel"]],"conceptLinks":[["Prix coté + coupon couru","Le prix au pied du coupon exclut les intérêts courus ; ajouter ces intérêts au règlement."],["Actualisation","Le prix théorique est la valeur actuelle des coupons et du remboursement."],["Taux et prix","Pour des flux fixes, une hausse du rendement exigé réduit leur valeur actuelle."]]},{"title":"Différents types d’obligations","label":"PARTIE 2 — MARCHÉ OBLIGATAIRE","number":7,"notes":[["Obligation à taux fixe","Elle verse un coupon calculé avec un taux contractuel fixe. Les flux d’intérêts sont connus à l’avance si l’émetteur respecte ses engagements. Son prix de marché peut néanmoins varier lorsque les taux exigés changent."],["Obligation à taux variable","Son coupon évolue selon un taux de référence prévu au contrat. Les intérêts perçus peuvent augmenter ou diminuer. Le cours peut être moins sensible à certains mouvements de taux, mais le capital n’est pas garanti contre tout risque."],["Comparer taux fixe et taux variable","Taux fixe : coupon stable, cours potentiellement sensible aux variations des taux. Taux variable : coupon ajusté, revenu moins prévisible. Dans les deux cas, l’investisseur conserve notamment un risque de défaut de l’émetteur."],["Obligation zéro coupon","Elle ne verse aucun coupon périodique. L’investisseur reçoit le montant de remboursement à l’échéance ; son rendement provient de la différence entre le prix d’achat et le montant reçu, sous réserve du paiement effectif."],["Obligation subordonnée","En cas de liquidation, une obligation subordonnée est remboursée après les créanciers de rang supérieur. Cette priorité plus faible augmente le risque de perte par rapport à une dette ordinaire comparable."],["Titres d’État","Les titres d’État sont des emprunts émis pour financer les besoins publics. Le support cite notamment les bons du Trésor marocain. L’investisseur prête à l’État et reçoit les flux prévus par le titre."],["Obligation verte","Une obligation verte est émise pour financer des projets environnementaux, comme les énergies renouvelables ou l’amélioration de l’efficacité énergétique. Son objet de financement la distingue d’une obligation ordinaire."],["Titres hybrides","Les titres hybrides combinent des caractéristiques de dette et de capital. Le support présente notamment les obligations convertibles en actions et les obligations remboursables en actions."],["Obligation convertible en actions (OCA)","Elle donne au porteur la possibilité, mais non l’obligation, de convertir sa créance en actions de l’émetteur selon des modalités prévues. L’investisseur peut ainsi bénéficier d’une hausse de l’action tout en conservant les caractéristiques de dette avant conversion."],["Obligation remboursable en actions","Son remboursement s’effectue en actions selon les conditions du contrat, contrairement à une obligation classique remboursée en numéraire. Elle ne doit pas être confondue avec une obligation convertible, qui comporte une option de conversion."]],"cards":[["Quel titre ne verse pas de coupon périodique et verse un montant à l’échéance ?","Le rendement du zéro coupon provient de l’écart entre prix payé et remboursement."],["Qu’est-ce qu’une obligation à taux fixe ?","Un titre dont le coupon est calculé à partir d’un taux contractuel fixe pendant la durée prévue."],["Qu’est-ce qu’une obligation à taux variable ?","Un titre dont le coupon évolue selon un taux de référence prévu au contrat."],["Quelle différence principale entre taux fixe et taux variable ?","À taux fixe, le coupon reste stable ; à taux variable, il s’ajuste et le revenu peut évoluer."],["Le prix d’une obligation à taux fixe reste-t-il constant ?","Non. Même avec un coupon fixe, le cours peut varier lorsque les taux de marché changent."],["Qu’est-ce qu’une obligation zéro coupon ?","Une obligation sans versements périodiques d’intérêts, remboursée en un seul paiement à l’échéance."],["Qu’est-ce qu’une obligation subordonnée ?","Une dette remboursée après des créanciers de rang supérieur en cas de liquidation de l’émetteur."],["Que représente un titre d’État ?","Un emprunt émis par l’État pour couvrir ses besoins de financement."],["Qu’est-ce qu’une obligation verte ?","Une obligation destinée à financer des projets ayant un objectif environnemental."],["Qu’est-ce qu’un titre hybride ?","Un instrument financier qui combine des caractéristiques d’obligation et d’action."],["Que signifie OCA ?","Obligation Convertible en Actions : un titre qui donne au porteur une possibilité de conversion en actions."],["Quelle différence entre obligation convertible et remboursable en actions ?","La convertible donne une option de conversion ; la remboursable en actions prévoit le remboursement en actions selon le contrat."],["Une obligation à taux variable élimine-t-elle le risque de défaut ?","Non. L’ajustement du coupon ne garantit pas la capacité de l’émetteur à rembourser."]],"quiz":[["Quel titre ne verse pas de coupon périodique et verse un montant à l’échéance ?",["Obligation zéro coupon","Obligation à taux variable","Obligation à coupon fixe ordinaire"],0,"Le rendement du zéro coupon provient de l’écart entre prix payé et remboursement."],["Quel type d’obligation verse un coupon fixé contractuellement ?",["L’obligation à taux fixe","L’obligation zéro coupon","L’obligation dont le coupon suit toujours l’inflation"],0,"Le taux fixe sert au calcul d’un coupon contractuel stable."],["Une obligation à taux variable a :",["Un taux de coupon fixé définitivement à l’émission","Un coupon qui peut évoluer avec un taux de référence","Un coupon indexé sur la valeur nominale sans référence à un taux de marché"],1,"Le revenu suit les modalités d’indexation prévues."],["Une obligation zéro coupon se caractérise par :",["Des intérêts payés tous les mois","Un droit de vote","L’absence de coupons périodiques"],2,"L’investisseur reçoit le montant prévu à l’échéance, sans coupons intermédiaires."],["En cas de liquidation, une dette subordonnée est généralement :",["Remboursée après les créanciers de rang supérieur","Remboursée au même rang qu’une dette ordinaire de premier rang","Remboursée avant les créanciers prioritaires dès que l’échéance est proche"],0,"La subordination place le créancier derrière d’autres catégories de créanciers."],["Quel titre sert à financer un projet environnemental ?",["Une action nominative uniquement","Une obligation verte","Un coupon couru"],1,"Les obligations vertes orientent les fonds levés vers des projets environnementaux."],["Une obligation convertible en actions donne au porteur :",["Un dividende obligatoire","Un droit de gestion immédiat","Une option de conversion en actions"],2,"L’investisseur peut exercer la conversion selon les clauses du titre."],["Le principal risque qui demeure pour une obligation à taux variable est notamment :",["Le risque de défaut de l’émetteur","L’interdiction de recevoir des intérêts","La suppression de toute échéance"],0,"Un coupon ajustable ne garantit pas le remboursement."],["Une obligation remboursable en actions prévoit :",["Un remboursement exclusivement en billets de banque","Une remise d’actions selon les modalités contractuelles","Un coupon nécessairement nul"],1,"Le remboursement peut prendre la forme d’actions, à distinguer d’une option de conversion."],["Un titre d’État correspond à :",["Une part du capital d’une entreprise privée","Un titre qui donne un droit de vote","Une dette émise pour financer l’État"],2,"Les titres d’État matérialisent un emprunt public."]],"map":[["Taux fixe","Coupon stable · Cours variable"],["Taux variable","Coupon indexé · Revenu variable"],["Zéro coupon","Pas de coupon périodique"],["Subordonnée","Rang de remboursement inférieur"],["Titres d’État","Financement public"],["Obligation verte","Projet environnemental"],["Titres hybrides","Dette + caractéristiques d’action"],["OCA","Option de conversion"],["Remboursable en actions","Remboursement prévu en actions"]],"conceptLinks":[["Profil des intérêts","Taux fixe : coupon stable ; variable : coupon indexé ; zéro coupon : pas de coupon périodique."],["Rang et finalité","Subordination, titres d’État et obligations vertes répondent à des caractéristiques différentes."],["Hybrides","Certains titres permettent ou prévoient un remboursement ou une conversion en actions."]]},{"title":"Risques, sensibilité et duration","label":"PARTIE 2 — MARCHÉ OBLIGATAIRE","number":8,"notes":[["Trois risques étudiés","Le support distingue le risque de défaut (non-paiement par l’émetteur), le risque de taux (variation du cours lorsque les taux changent) et le risque de liquidité (difficulté à vendre rapidement à un prix satisfaisant)."],["Risque de défaut","L’émetteur peut ne pas payer un coupon ou ne pas rembourser le capital. Une rémunération prévue au contrat ne supprime donc pas le risque de perte pour le détenteur."],["Agences de notation","Standard & Poor’s, Moody’s et Fitch évaluent la qualité de crédit des émetteurs ou des titres. Une notation donne une appréciation du risque de défaut, pas une garantie de remboursement."],["Lire les grandes catégories de notation","Le support présente des notes élevées comme AAA, AA et A, puis BBB ; les catégories plus basses, comme BB et en dessous, correspondent à un risque de crédit plus élevé. Les échelles exactes varient selon les agences."],["Risque de taux","Pour une obligation à flux fixes, le cours évolue généralement en sens inverse du rendement exigé : taux de marché en hausse → cours en baisse ; taux en baisse → cours en hausse."],["Risque de liquidité","Un investisseur qui veut revendre avant l’échéance peut ne pas trouver facilement d’acheteur. Il peut alors devoir attendre ou accepter un prix moins favorable."],["Sensibilité : variation observée du prix","Le support exprime la variation relative du prix par S_obs = (P1 − P0) / P0, où P0 est le prix initial et P1 le prix après variation des taux. Cette formule mesure une variation de prix pour le mouvement de taux considéré."],["Duration : définition","La duration est la moyenne pondérée des dates de réception des flux futurs (coupons et remboursement), pondérées par leur valeur actuelle. Elle s’exprime en unités de temps, par exemple en années."],["Lien duration et sensibilité aux taux","Le support donne S_taux = −D / (1 + r), où D est la duration et r le rendement par période. Ce coefficient décrit la variation relative approximative du prix pour une variation unitaire du taux : ΔP / P ≈ S_taux × Δr."],["Ne pas confondre les deux expressions de S","(P1 − P0) / P0 est la variation relative effectivement constatée du prix. −D / (1 + r) est un coefficient de sensibilité aux taux, utilisé pour estimer cette variation lorsque le taux change légèrement."],["Interprétation du signe négatif","La sensibilité aux taux est généralement négative pour une obligation classique à flux fixes : quand le taux exigé augmente, la valeur actuelle des paiements futurs diminue."],["Utilité pratique de la duration","À caractéristiques comparables, une duration plus élevée signifie généralement une plus forte sensibilité du prix aux variations de taux. Elle aide à comparer les risques de taux de plusieurs obligations."]],"cards":[["Un titre passe de 100 DH à 96 DH. Quelle variation relative observée ?","(96 − 100)/100 = −0,04, soit −4 %."],["Quels sont les trois risques obligataires présentés dans le cours ?","Le risque de défaut, le risque de taux et le risque de liquidité."],["Qu’est-ce que le risque de défaut ?","Le risque que l’émetteur ne paie pas les intérêts ou ne rembourse pas le capital prévu."],["À quoi servent les agences de notation ?","À évaluer la qualité de crédit d’un émetteur ou d’une dette, pour apprécier le risque de défaut."],["Quelles sont les principales agences de notation citées ?","Standard & Poor’s, Moody’s et Fitch."],["Qu’est-ce que le risque de taux ?","Le risque de variation du cours d’une obligation lorsque les taux d’intérêt du marché changent."],["Qu’est-ce que le risque de liquidité ?","La difficulté éventuelle à revendre rapidement une obligation à un prix satisfaisant."],["Si les taux de marché montent, que devient généralement le prix d’une obligation à taux fixe ?","Il baisse, car ses paiements futurs sont actualisés à un taux plus élevé."],["Comment mesurer la variation relative observée du prix d’une obligation ?","Variation relative = (P1 − P0) / P0, avec P0 prix initial et P1 prix après le changement."],["Qu’est-ce que la duration d’une obligation ?","La moyenne pondérée des échéances des flux futurs, pondérées par leur valeur actuelle."],["Quelle relation le cours donne-t-il entre sensibilité aux taux et duration ?","Sensibilité aux taux ≈ −D / (1 + r), avec D la duration et r le taux de rendement par période."],["Comment estimer l’effet d’une petite variation du taux sur le prix ?","Variation relative du prix ≈ [−D / (1 + r)] × variation du taux, exprimée en valeur décimale."],["Pourquoi la sensibilité aux taux est-elle généralement négative ?","Parce qu’une hausse du taux d’actualisation diminue la valeur actuelle des flux futurs fixes."],["Que signifie une duration plus élevée, toutes choses égales par ailleurs ?","Une exposition généralement plus forte du prix aux variations des taux de marché."],["Une notation élevée supprime-t-elle le risque de défaut ?","Non. Elle indique une meilleure qualité de crédit estimée, sans garantir le remboursement."]],"quiz":[["Un titre passe de 100 DH à 96 DH. Quelle variation relative observée ?",["−4 %","+4 %","−0,4 %"],0,"(96 − 100)/100 = −0,04, soit −4 %."],["Le risque de défaut correspond :",["À une baisse du volume des échanges seulement","À l’impossibilité éventuelle pour l’émetteur de payer","À un changement du nom de l’obligation"],1,"Le risque de défaut concerne le paiement des coupons et du capital."],["Quel risque concerne la difficulté de revendre un titre ?",["Le risque de liquidité","Le risque de conversion","Le risque d’amortissement constant"],0,"La liquidité mesure la facilité de trouver une contrepartie et de vendre."],["Quel organisme évalue notamment le risque de crédit ?",["La seule société émettrice","Le teneur de marché uniquement","Une agence de notation comme Moody’s"],2,"Les agences attribuent des notations pour aider à apprécier le risque de remboursement."],["Quand les taux de marché augmentent, le cours d’une obligation à taux fixe :",["Monte automatiquement","Tend à baisser","Devient égal à son nominal"],1,"La valeur actuelle des flux fixes baisse quand le taux d’actualisation augmente."],["La formule (P1 − P0) / P0 mesure :",["La variation relative observée du prix","Le montant du coupon annuel","La durée résiduelle en années"],0,"Cette expression compare le prix après changement au prix initial."],["La duration correspond :",["Au nombre d’actionnaires de l’émetteur","Au taux facial de l’obligation","À une moyenne pondérée des échéances des flux actualisés"],2,"La duration combine le calendrier des flux et leurs valeurs actuelles."],["Quelle relation exprime le coefficient de sensibilité aux taux dans le support ?",["S = VN × TN","S = −D / (1 + r)","S = prix d’émission − nominal"],1,"Le coefficient lié à la duration est négatif pour une obligation classique à flux fixes."],["Une duration plus longue implique généralement :",["Une sensibilité du prix plus forte aux taux","Un risque de défaut toujours nul","Un coupon obligatoirement variable"],0,"À autres conditions comparables, la duration amplifie l’effet d’une variation des taux."],["Une notation de crédit signifie :",["Un remboursement garanti par la notation","Un droit de vote sur l’émetteur","Une appréciation du risque de crédit"],2,"Une notation évalue un risque mais ne garantit pas le paiement."],["Quelle formule sert à estimer l’effet d’un petit mouvement de taux ?",["ΔP/P ≈ coupon × nominal","ΔP/P ≈ [−D/(1+r)] × Δr","ΔP/P = nombre d’actions × taux facial"],1,"La variation relative estimée combine la sensibilité et la variation du rendement."]],"map":[["Risques","Défaut · Taux · Liquidité"],["Défaut","Coupons ou capital non payés"],["Notation","S&P · Moody’s · Fitch"],["Risque de taux","Taux ↑ → Prix ↓"],["Liquidité","Difficulté de revente"],["Variation observée","(P1 − P0)/P0"],["Duration","Échéances moyennes pondérées des flux"],["Sensibilité aux taux","−D/(1+r)"],["Estimation","ΔP/P ≈ Sensibilité × Δr"]],"conceptLinks":[["Risques","Défaut : non-paiement ; liquidité : revente difficile ; taux : variation du prix."],["Duration","Moyenne des dates de flux pondérées par leur valeur actuelle."],["Sensibilité","−D/(1+r) approxime l’effet d’une petite variation du taux sur le prix ; ne pas confondre avec variation constatée."]]}];
